//! State oracle for the gr/grt*.c per-stage TU ports (generated by cref/gen_grt_stages.py).
//!
//! The reference side is the UNMODIFIED game C (src/melee/gr/<stem>.c plus the verbatim
//! gr/inlines.h and jobj.h inlines) compiled natively with recorder stubs for every callee
//! (cref/gen_grt_stages_ref.sh -> tests/data/tu_<stem>_ref.txt, one FNV-1a hash per case).
//! This file replays the identical scripted world on the Rust port: a seeded fixture of three
//! gobj/Ground/JObj triples (+2 items, stage_info, pad status), every function called with seeded
//! arguments, the callee call sequence (with arguments and seeded return values) and the whole
//! fixture state afterwards (Ground callbacks, JObj flags/scale/rotation, stage_info bits, the
//! TU's own statics) hashed into the case line. Also the StageCallbacks/StageData tables.
#![allow(non_snake_case, non_upper_case_globals, static_mut_refs, unused_variables, unused_unsafe, clippy::all)]
use core::ffi::{c_void, CStr};
use core::ptr::{addr_of_mut, null_mut};
use std::cell::{Cell, RefCell};
use std::sync::Mutex;

use melee_types::*;
use melee_world::gr::inlines;

static LOCK: Mutex<()> = Mutex::new(());
static NONULL: std::sync::atomic::AtomicBool = std::sync::atomic::AtomicBool::new(false);

pub struct World {
    pub g: *mut HSD_GObj,
    pub r: *mut Ground,
    pub j: *mut HSD_JObj,
    pub ig: *mut HSD_GObj,
    pub it: *mut Item,
    pub p: Vec3,
    pub yak: *mut [*mut DynamicsDesc; 4],
    pub d: *mut DynamicsDesc,
    pub stage_info: *mut StageInfo,
    pub pad: *mut HSD_PadStatus,
}

thread_local! {
    static WP: Cell<*mut World> = const { Cell::new(null_mut()) };
    static TR: RefCell<String> = const { RefCell::new(String::new()) };
    static SEED: Cell<u32> = const { Cell::new(1) };
    static MUTED: Cell<bool> = const { Cell::new(false) };
    static REG: RefCell<std::vec::Vec<(usize, String)>> = const { RefCell::new(std::vec::Vec::new()) };
}

fn w() -> &'static mut World {
    WP.with(|p| {
        if p.get().is_null() {
            unsafe {
                let z = |n: usize| -> *mut u8 { Box::leak(vec![0u64; n].into_boxed_slice()).as_mut_ptr().cast() };
                let wd = World {
                    g: z(3 * core::mem::size_of::<HSD_GObj>() / 8 + 8).cast(),
                    r: z(3 * core::mem::size_of::<Ground>() / 8 + 8).cast(),
                    j: z(3 * core::mem::size_of::<HSD_JObj>() / 8 + 8).cast(),
                    ig: z(2 * core::mem::size_of::<HSD_GObj>() / 8 + 8).cast(),
                    it: z(2 * core::mem::size_of::<Item>() / 8 + 8).cast(),
                    p: core::mem::zeroed(),
                    yak: z(4).cast(),
                    d: z(4 * core::mem::size_of::<DynamicsDesc>() / 8 + 8).cast(),
                    stage_info: z(core::mem::size_of::<StageInfo>() / 8 + 8).cast(),
                    pad: z(4 * core::mem::size_of::<HSD_PadStatus>() / 8 + 8).cast(),
                };
                p.set(Box::leak(Box::new(wd)));
            }
        }
        unsafe { &mut *p.get() }
    })
}

fn rec(s: &str) {
    if !MUTED.with(|m| m.get()) {
        TR.with(|t| t.borrow_mut().push_str(s));
    }
}
fn set_muted(m: bool) {
    MUTED.with(|x| x.set(m));
}
fn rnd() -> u32 {
    SEED.with(|s| {
        let mut x = s.get();
        x ^= x << 13;
        x ^= x >> 17;
        x ^= x << 5;
        s.set(x);
        x
    })
}
fn rf() -> f32 {
    (((rnd() % 2000) as i32) - 1000) as f32 / 16.0f32
}
fn sym(p: usize) -> String {
    if p == 0 {
        return "0".to_string();
    }
    REG.with(|r| r.borrow().iter().find(|e| e.0 == p).map(|e| e.1.clone()).unwrap_or_else(|| "?".to_string()))
}
fn fname(p: usize) -> String {
    sym(p)
}
fn fnv(s: &str) -> u64 {
    let mut h: u64 = 1469598103934665603;
    for b in s.bytes() {
        h ^= b as u64;
        h = h.wrapping_mul(1099511628211);
    }
    h
}
fn begin_case(name: &str, c: usize, seed: u32) {
    TR.with(|t| t.borrow_mut().clear());
    SEED.with(|s| s.set(seed));
    rec(&format!("{} #{}", name, c));
}
fn end_case(out: &mut String) {
    let tr = TR.with(|t| t.borrow().clone());
    let cut = tr.find('#').map(|i| tr[i..].find(' ').map_or(tr.len(), |k| i + k)).unwrap_or(tr.len());
    out.push_str(&format!("{} {:016x}\n", &tr[..cut], fnv(&tr)));
    if std::env::var("GRT_VERBOSE").is_ok() {
        eprintln!("{}", tr);
    }
}
unsafe extern "C" fn sentinel_fn(_g: *mut HSD_GObj) {}

unsafe fn reset_world(float_global: bool, gt_setter: Option<&dyn Fn(f32)>) {
    let w = w();
    for i in 0..3 {
        let g = w.g.add(i);
        let r = w.r.add(i);
        let j = w.j.add(i);
        (*g).hsd_obj = j.cast();
        (*g).user_data = r.cast();
        core::ptr::write_bytes(r, 0, 1);
        (*r).map_id = rnd() % 64;
        (*r).x8_callback = Some(sentinel_fn);
        (*r).xC_callback = Some(sentinel_fn);
        (*r).x1C_callback = Some(sentinel_fn);
        core::ptr::write_bytes(j, 0, 1);
        (*j).flags = rnd() & (0x10u32 | 0x40 | 0x2000000 | 0x800000 | 0xFF00);
        (*j).scale.x = rf();
        (*j).scale.y = rf();
        (*j).scale.z = rf();
        (*j).rotate.z = rf();
        (*j).translate.x = rf();
        (*j).translate.y = rf();
        (*j).translate.z = rf();
    }
    for i in 0..2 {
        let it = w.it.add(i);
        core::ptr::write_bytes(it, 0, 1);
        let ig = w.ig.add(i);
        (*ig).hsd_obj = w.j.add(i).cast();
        (*ig).user_data = it.cast();
        (*it).xDD4_itemVar.mato.x0 = w.j.add((i + 1) % 3);
        (*it).xDD4_itemVar.mato.x4 = w.j.add(i);
    }
    w.p.x = rf();
    w.p.y = rf();
    w.p.z = rf();
    for i in 0..4 {
        (*w.yak)[i] = w.d.add(i);
    }
    (*w.stage_info).unk8C.set_b4((rnd() & 1) as u8);
    (*w.stage_info).unk8C.set_b5((rnd() & 1) as u8);
    for i in 0..4 {
        let p = w.pad.add(i);
        (*p).button = rnd() & 0xFFFF;
        (*p).last_button = 0;
        (*p).trigger = rnd() & 0xFFFF;
    }
    if float_global {
        const FT: [f32; 5] = [1.2217305f32, -1.2217305f32, 1.1344640f32, -1.1344640f32, 0.0f32];
        let r = rnd();
        let v = if r & 1 != 0 { FT[((r >> 1) % 5) as usize] } else { (((r >> 4) % 2600) as i32 - 1300) as f32 / 1000.0f32 };
        (gt_setter.unwrap())(v);
    }
}

unsafe fn snapshot_with(gt: Option<f32>, yak: Option<usize>) {
    let w = w();
    for i in 0..3 {
        let r = w.r.add(i);
        let j = w.j.add(i);
        rec(&format!(" |G{} map={} x8={} xC={} x1C={}", i, (*r).map_id, fname((*r).x8_callback.map_or(0, |f| f as usize)),
            fname((*r).xC_callback.map_or(0, |f| f as usize)), fname((*r).x1C_callback.map_or(0, |f| f as usize))));
        rec(&format!(" J{} f={:x} s={:08x},{:08x},{:08x} rz={:08x} t={:08x},{:08x},{:08x}", i, (*j).flags, (*j).scale.x.to_bits(),
            (*j).scale.y.to_bits(), (*j).scale.z.to_bits(), (*j).rotate.z.to_bits(), (*j).translate.x.to_bits(), (*j).translate.y.to_bits(), (*j).translate.z.to_bits()));
    }
    for i in 0..2 {
        let it = w.it.add(i);
        rec(&format!(" I{} x0={} x4={}", i, sym((*it).xDD4_itemVar.mato.x0 as usize), sym((*it).xDD4_itemVar.mato.x4 as usize)));
    }
    rec(&format!(" si={}{} P={:08x},{:08x},{:08x}", (*w.stage_info).unk8C.b4(), (*w.stage_info).unk8C.b5(), w.p.x.to_bits(), w.p.y.to_bits(), w.p.z.to_bits()));
    if let Some(g) = gt {
        rec(&format!(" gt={:08x}", g.to_bits()));
    }
    if let Some(y) = yak {
        rec(&format!(" yak={}", sym(y)));
    }
}

fn rf_for_hooks() -> f32 {
    rf()
}

/// Recorder hooks (the Rust twins of the C stubs in the generated prelude.h).
mod hooks {
    use super::*;
    pub unsafe fn h_grAnime_801C8138(g: *mut HSD_GObj, m: i32, b: i32) {
        rec(&format!(" anim({},{},{})", sym(g as usize), m, b));
    }
    pub unsafe fn h_Ground_InitMapColl(j: *mut HSD_JObj, m: i32) -> i32 {
        rec(&format!(" imc({},{})", sym(j as usize), m)); 1
    }
    pub unsafe fn h_Ground_UpdateMapColl(g: *mut HSD_GObj) -> i32 {
        rec(&format!(" umc({})", sym(g as usize))); 1
    }
    pub unsafe fn h_lb_800115F4() {
        rec(" lb()");
    }
    pub unsafe fn h_GObj_SetupGXLink(g: *mut HSD_GObj, cb: GObj_RenderFunc, gx: u8, pri: u32) {
        rec(&format!(" gxlink({},{},{},{})", sym(g as usize), fname(cb.map_or(0, |f| f as usize)), gx, pri));
    }
    pub unsafe fn h_Mex_GrBind(f: *mut c_void) -> *mut c_void {
        rec(&format!(" mex({})", fname(f as usize))); f
    }
    pub unsafe fn h_HSD_GObj_SetupProc(g: *mut HSD_GObj, f: HSD_GObjEvent, pri: u8) {
        rec(&format!(" proc({},{},{})", sym(g as usize), fname(f.map_or(0, |f| f as usize)), pri));
    }
    pub unsafe fn h_stage_info() -> *mut StageInfo {
        w().stage_info
    }
    pub unsafe fn h_Ground_801C39C0() {
        rec(" g39C0()");
    }
    pub unsafe fn h_Ground_801C3BB4() {
        rec(" g3BB4()");
    }
    pub unsafe fn h_Ground_801C4210() {
        rec(" g4210()");
    }
    pub unsafe fn h_Ground_801C42AC() {
        rec(" g42AC()");
    }
    pub unsafe fn h_OSReport(fmt: &CStr, file: &CStr, line: i32, id: i32) {
        rec(&format!(" OSReport({},{},{},{})", fmt.to_str().unwrap(), file.to_str().unwrap(), line, id));
    }
    pub unsafe fn h_Ground_GetStageGObj(id: i32) -> *mut HSD_GObj {
        let r = rnd(); let g = if r & 3 == 0 && !NONULL.load(std::sync::atomic::Ordering::Relaxed) { null_mut() } else { w().g.add(((r >> 2) % 3) as usize) }; rec(&format!(" GetStageGObj({})={}", id, sym(g as usize))); g
    }
    pub unsafe fn h_Ground_GetYakumonoParam() -> *mut c_void {
        rec(&format!(" GetYakumonoParam()={}", sym(w().yak as usize))); w().yak.cast()
    }
    pub unsafe fn h_grZakoGenerator_801CAE04(d: *mut c_void) {
        rec(&format!(" zako({})", sym(d as usize)));
    }
    pub unsafe fn h_mpJointFromLine(line: i32) -> i32 {
        const T: [i32; 5] = [-1, 0, 1, 2, 0]; let r = T[(rnd() % 5) as usize]; rec(&format!(" mpJointFromLine({})={}", line, r)); r
    }
    pub unsafe fn h_mpLineGetKind(line: i32) -> i32 {
        const T: [i32; 6] = [1, 2, 4, 8, 0, 16]; let r = T[(rnd() % 6) as usize]; rec(&format!(" mpLineGetKind({})={}", line, r)); r
    }
    pub unsafe fn h_HSD_PadMasterStatus() -> *mut HSD_PadStatus {
        w().pad
    }
    pub unsafe fn h_Ground_801C3FA4(g: *mut HSD_GObj, depth: i32) -> *mut HSD_JObj {
        let r = rnd(); let j = if r % 3 == 0 { null_mut() } else { w().j.add(((r >> 3) % 3) as usize) }; rec(&format!(" g3FA4({},{})={}", sym(g as usize), depth, sym(j as usize))); j
    }
    pub unsafe fn h_HSD_JObjGetFlags(j: *mut HSD_JObj) -> u32 {
        let f = if j.is_null() { 0 } else { (*j).flags }; rec(&format!(" getflags({})={:x}", sym(j as usize), f)); f
    }
    pub unsafe fn h_HSD_JObjSetFlags(j: *mut HSD_JObj, f: u32) {
        if !j.is_null() { (*j).flags |= f; } rec(&format!(" setflags({},{:x})", sym(j as usize), f));
    }
    pub unsafe fn h_HSD_JObjClearFlags(j: *mut HSD_JObj, f: u32) {
        if !j.is_null() { (*j).flags &= !f; } rec(&format!(" clearflags({},{:x})", sym(j as usize), f));
    }
    pub unsafe fn h_HSD_JObjSetFlagsAll(j: *mut HSD_JObj, f: u32) {
        if !j.is_null() { (*j).flags |= f; } rec(&format!(" setall({},{:x})", sym(j as usize), f));
    }
    pub unsafe fn h_HSD_JObjSetMtxDirtySub(j: *mut HSD_JObj) {
        (*j).flags |= JOBJ_MTX_DIRTY as u32; rec(&format!(" dirty({})", sym(j as usize)));
    }
    pub unsafe fn h_Ground_801C33C0(a: i32, b: i32) -> i32 {
        const T: [i32; 5] = [-1, 0, 3, 7, 12]; let r = T[(rnd() % 5) as usize]; rec(&format!(" g33C0({},{})={}", a, b, r)); r
    }
    pub unsafe fn h_grMaterial_801C8CFC(a: i32, b: i32, gp: *mut Ground, j: *mut HSD_JObj, cb4: *const c_void, cb5: Option<unsafe extern "C" fn(*mut HSD_GObj, *mut Ground, *mut Vec3, *mut HSD_GObj, f32)>, cb6: *const c_void) -> *mut HSD_GObj {
        let r = rnd(); let it = if r % 3 == 0 { null_mut() } else { w().ig.add(((r >> 2) % 2) as usize) }; rec(&format!(" mat8CFC({},{},{},{},{},{},{})={}", a, b, sym(gp as usize), sym(j as usize), fname(cb4 as usize), fname(cb5.map_or(0, |f| f as usize)), fname(cb6 as usize), sym(it as usize))); it
    }
    pub unsafe fn h_grMaterial_801C8DE0(g: *mut HSD_GObj, a: f32, b: f32, c: f32, d: f32, e: f32, f: f32, h: f32) {
        rec(&format!(" mat8DE0({},{:08x},{:08x},{:08x},{:08x},{:08x},{:08x},{:08x})", sym(g as usize), a.to_bits(), b.to_bits(), c.to_bits(), d.to_bits(), e.to_bits(), f.to_bits(), h.to_bits()));
    }
    pub unsafe fn h_grMaterial_801C8E08(g: *mut HSD_GObj) {
        rec(&format!(" mat8E08({})", sym(g as usize)));
    }
    pub unsafe fn h_grMaterial_801C8CDC(g: *mut HSD_GObj) {
        rec(&format!(" mat8CDC({})", sym(g as usize)));
    }
    pub unsafe fn h_Ground_801C53EC(a: u32) {
        rec(&format!(" g53EC({})", a));
    }
    pub unsafe fn h_Camera_RequestQuake(kind: i32, pos: *mut Vec3) {
        rec(&format!(" quake({},{})", kind, sym(pos as usize)));
    }
    pub unsafe fn h_efSync_Spawn(id: i32, g: *mut HSD_GObj, pos: *mut Vec3) {
        rec(&format!(" efSync({},{},{:08x},{:08x},{:08x})", id, sym(g as usize), (*pos).x.to_bits(), (*pos).y.to_bits(), (*pos).z.to_bits()));
    }
    pub unsafe fn h_lb_8000B1CC(j: *mut HSD_JObj, a: *const Vec3, out: *mut Vec3) {
        (*out).x = rf(); (*out).y = rf(); (*out).z = rf(); rec(&format!(" lb1CC({},{})", sym(j as usize), sym(a as usize)));
    }
    pub unsafe fn h_grAnime_801C7FF8(g: *mut HSD_GObj, a: i32, b: i32, c: i32, d: f32, e: f32) {
        rec(&format!(" anim7FF8({},{},{},{},{:08x},{:08x})", sym(g as usize), a, b, c, d.to_bits(), e.to_bits()));
    }
}

